'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './sunburst.css'

export type SunburstProps = React.ComponentPropsWithoutRef<'div'> & {
    color?: string
    /** Number of rays. */
    rays?: number
    /** Where the rays come from, as "x y" percentages, e.g. "50% 100%" for the bottom edge. */
    origin?: string
    /** Seconds per full turn. */
    speed?: number
    paused?: boolean
}

// Rays fanning out from a point, turning very slowly. Retro posters, celebrations.
const Sunburst = ({ color = 'rgba(250, 204, 21, 0.14)', rays = 18, origin = '50% 50%', speed = 60, paused = false, className, style, children, ...props }: SunburstProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-sunburst', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-sun-color': color, '--rad-fx-sun-step': `${360 / rays}deg`, '--rad-fx-sun-x': origin.split(' ')[0], '--rad-fx-sun-y': origin.split(' ')[1] ?? '50%', '--rad-fx-sun-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-sunburst-layer" aria-hidden="true">
            <span className="rad-fx-sunburst-rays" />
        </div>
        <div className="rad-fx-sunburst-content">{children}</div>
    </div>
}

export default Sunburst

.rad-fx-sunburst {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-sunburst-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-sunburst-content { position: relative; }

.rad-fx-sunburst[data-state='paused'] .rad-fx-sunburst-layer,
.rad-fx-sunburst[data-state='paused'] .rad-fx-sunburst-layer * { animation-play-state: paused !important; }

.rad-fx-sunburst-rays {
    position: absolute;
    left: var(--rad-fx-sun-x, 50%);
    top: var(--rad-fx-sun-y, 50%);
    width: 300%;
    aspect-ratio: 1;
    translate: -50% -50%;
    background: repeating-conic-gradient(from 0deg at 50% 50%, var(--rad-fx-sun-color) 0deg calc(var(--rad-fx-sun-step, 20deg) / 2), transparent calc(var(--rad-fx-sun-step, 20deg) / 2) var(--rad-fx-sun-step, 20deg));
    mask-image: radial-gradient(circle at center, #000 0%, transparent 45%);
    animation: rad-fx-sunburst var(--rad-fx-sun-speed, 60s) linear infinite;
}

@keyframes rad-fx-sunburst { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-sunburst-rays { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-sunburst-rays { animation: none; }
